//! GENERATED by verify/probes/_fit/m111_gen_corpus.rs.py -- do not hand-edit.
//! Each case: archived .reg fixture pair -> expected sbs table BODY lines
//! (header/rule excluded), from the m101 sbs tables on BOTH installs --
//! `locale: "ZH"` cells come from the Chinese repack runs, `"EN"` cells
//! from the English reference runs (docs/17 sec sbs/geometry).

use reacmp_reg::engine::{render_body_lines, Locale};
use reacmp_reg::parse::parse_reg_text;

pub struct CorpusCase {
    pub tag: &'static str,
    pub locale: &'static str,
    pub left: &'static str,
    pub right: &'static str,
    pub expect: &'static [&'static str],
}

#[test]
fn corpus_sbs_tables_match_the_archived_reports() {
    let mut fails = Vec::new();
    for c in CASES {
        let loc = if c.locale == "ZH" { &Locale::ZH } else { &Locale::EN };
        let l = parse_reg_text(c.left);
        let r = parse_reg_text(c.right);
        let got = render_body_lines(&l, &r, loc);
        if got != c.expect {
            fails.push(format!("--- {t} [{lo}]\nwant:\n{}\ngot:\n{}",
                c.expect.iter().map(|x| format!("   {x:?}")).collect::<Vec<_>>().join("\n"),
                got.iter().map(|x| format!("   {x:?}")).collect::<Vec<_>>().join("\n"),
                t = c.tag, lo = c.locale));
        }
    }
    assert!(fails.is_empty(), "{} failing of {}:\n{}", fails.len(), CASES.len(), fails.join("\n"));
}

